const form=document.querySelector('#workflow'), results=document.querySelector('#results'), status=document.querySelector('#status');
let language='zh';try{language=localStorage.getItem('exchangeprep_language')==='en'?'en':'zh';}catch{}
let output=null, offlineOutput=false, busy=false, statusKey='ready', statusArgs={};
const cfg=window.EXCHANGEPREP_CONFIG||{};
const apiBase=cfg.backendUrl?cfg.backendUrl.replace(/\/$/,''):(location.hostname.endsWith('github.io')?null:location.origin);
const t=(key,args={})=>(COPY[language][key]||key).replace(/\{(\w+)\}/g,(_,k)=>args[k]??'');
const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(cls)node.className=cls;return node;};
function setStatus(key,args={}){statusKey=key;statusArgs=args;status.textContent=t(key,args);}
function setLanguage(value){language=value;try{localStorage.setItem('exchangeprep_language',value);}catch{}document.documentElement.lang=value==='en'?'en':'zh-CN';document.title=value==='en'?'ExchangePrep · Application planning':'ExchangePrep · 海外学习申请规划';for(const node of document.querySelectorAll('[data-i18n]')){if(node.dataset.i18n==='hero')node.innerHTML=t('hero');else node.textContent=t(node.dataset.i18n);}for(const node of document.querySelectorAll('[data-placeholder]'))node.placeholder=t(node.dataset.placeholder);document.querySelector('#language-button').textContent=value==='zh'?'English ↗':'中文 ↗';document.querySelector('#language-button').setAttribute('aria-label',value==='zh'?'Switch to English':'切换至中文');setStatus(statusKey,statusArgs);if(!apiBase){document.querySelector('#backend-note').hidden=false;document.querySelector('#backend-note').textContent=t('backendUnavailable');}if(output)render(output,offlineOutput);}
function safeLink(url,label){try{const parsed=new URL(url,apiBase||location.origin);if(!['http:','https:'].includes(parsed.protocol))return el('span',label||url);const a=el('a',label||url);a.href=parsed.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch{return el('span',label||url);}}
function linkedText(text){const p=el('p');for(const part of String(text).split(/(https?:\/\/[^\s<>()\[\]，。；]+)/g))p.append(/^https?:\/\//.test(part)?safeLink(part,part):document.createTextNode(part));return p;}
function fold(label,items,cls='diagnostics'){if(!items.length)return null;const details=el('details',undefined,cls);details.append(el('summary',label));for(const item of items)details.append(linkedText(item));return details;}
function render(data,offline){results.replaceChildren();results.hidden=false;const intro=el('div',undefined,'card');intro.append(el('p',t('resultEyebrow'),'eyebrow'),el('h2',t(offline?'offlineTitle':'resultTitle'),'results-title'),el('p',t('assumption'),'muted'));if(offline)intro.append(el('p',t('offlineNote'),'notice'));if(data.research.request.language!==language)intro.append(el('p',t('languageNote'),'notice'));
intro.append(el('p',t('meta',{date:data.assumptions.departure_date,duration:data.assumptions.duration_days,buffer:data.assumptions.buffer_days}),'result-meta'));
if(!offline&&data.research.coverage_summary)intro.append(el('p',data.research.coverage_summary,'notice'));
const reviews=data.research.candidate_reviews||[];if(reviews.length){const notes=el('details',undefined,'diagnostics');notes.append(el('summary',t('candidateReviews')));for(const review of reviews){notes.append(el('p',`${review.name} · ${t(review.status==='excluded'?'excluded':'unconfirmedCandidate')}: ${review.reason}`),safeLink(review.url,t('original')));for(const evidence of review.evidence||[])notes.append(el('p',evidence.quote,'muted'));}intro.append(notes);}
const warnings=data.research.warnings||[];const warningsFold=fold(t('researchWarnings',{count:warnings.length}),warnings);if(warningsFold)intro.append(warningsFold);results.append(intro);
if(!data.plans.length)intro.append(el('p',t('empty'),'notice'));
data.plans.forEach((plan,i)=>{const programme=data.research.programmes[i],card=el('article',undefined,'card'),heading=el('div',undefined,'plan-head'),name=el('div');name.append(el('span',`${String(i+1).padStart(2,'0')} / ${String(data.plans.length).padStart(2,'0')}`,'plan-index'),el('h2',programme.name));if(programme.official_url)name.append(safeLink(programme.official_url,t('officialUrl')));heading.append(name,el('span',t(plan.feasibility),'badge'));card.append(heading);
const notes=(plan.conflicts||[]).map(c=>language==='en'?c.detail:c.detail_plain||c.detail);const conflicts=fold(t('conflicts',{count:notes.length}),notes);if(conflicts)card.append(conflicts);
const names=Object.fromEntries(plan.entries.map(e=>[e.task_id,e.title_plain||e.title]));
for(const entry of plan.entries){const row=el('div',undefined,'step');row.append(el('h3',`${entry.order}. ${entry.title_plain||entry.title}`));if(entry.action)row.append(el('p',entry.action,'action'));const dates=el('div',undefined,'dates');for(const [label,value] of [['recommended',entry.recommended_start],['latest',entry.latest_start],['deadline',entry.deadline]]){const d=el('div');d.append(el('small',t(label)),el('strong',value||t('unconfirmed')));dates.append(d);}row.append(dates);
if(entry.prerequisites.length)row.append(el('p',t('prerequisites')+entry.prerequisites.map(id=>names[id]||id).join(language==='en'?', ':'、'),'muted'));
if(entry.channel)row.append(linkedText(t('channel')+entry.channel));if(entry.documents.length)row.append(el('p',t('documents')+entry.documents.join(language==='en'?', ':'、')));if(entry.applies_if)row.append(el('p',t('applies')+entry.applies_if,'muted'));
const details=el('details');details.append(el('summary',t('sources')));const step=programme.steps.find(s=>s.id===entry.task_id);if(step?.deadline.raw)details.append(el('p',t('raw')+step.deadline.raw));for(const source of entry.sources||[]){details.append(el('p',source.quote,'muted'));if(source.url)details.append(safeLink(source.url,t('original')));}
const warnings=language==='en'?[...(entry.blocking_conflicts||[]),...(entry.warnings||[])]:[...(entry.blocking_plain||[]),...(entry.warnings_plain||[])];for(const note of warnings)details.append(el('p',note,'muted'));row.append(details);card.append(row);}
const questions=programme.unresolved_questions||[];const more=fold(t('questions',{count:questions.length}),questions);if(more)card.append(more);results.append(card);});
const sources=el('details',undefined,'card sources');sources.append(el('summary',t('allSources')));for(const source of data.research.sources){const p=el('p');p.append(safeLink(source.url,source.title),el('span',' · '+t(source.read_status)));sources.append(p);}for(const attempt of data.research.search_log||[])sources.append(el('p',`${attempt.query} · ${t(attempt.status==='empty'?'emptySearch':attempt.status)} · ${attempt.result_count}`));results.append(sources);document.querySelector('#downloads').hidden=false;}
function payload(){const data=Object.fromEntries(new FormData(form));for(const k of ['year_of_study','max_programmes','duration_days','buffer_days'])data[k]=data[k]?Number(data[k]):null;data.programme_url=data.programme_url||null;data.language=language;return data;}
async function readResponse(response){let data;try{data=await response.json();}catch{throw Error(t('retry'));}if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:t('validation'));return data;}
async function submit(offline){if(!form.reportValidity())return;const key=document.querySelector('#key').value.trim();if(!offline&&!key){setStatus('keyRequired');return;}if(!offline&&!apiBase){setStatus('backendUnavailable');return;}busy=true;for(const b of form.querySelectorAll('button'))b.disabled=true;document.querySelector('#progress').hidden=false;document.querySelector('#downloads').hidden=true;results.hidden=true;output=null;const started=Date.now();const update=()=>setStatus(offline?'offlineBusy':'busy',{seconds:Math.round((Date.now()-started)/1000)});update();const timer=setInterval(update,1000);
try{let data;if(offline&&!apiBase){data=await readResponse(await fetch(`./static/sample-workflow-${language}.json`,{cache:'no-store'}));}else{const path=offline?'/api/workflow/sample':'/api/workflow/jobs';data=await readResponse(await fetch(apiBase+path,{method:'POST',headers:{'Content-Type':'application/json',...(offline?{}:{'X-API-Key':key})},body:JSON.stringify(payload()),cache:'no-store'}));if(!offline){const job=data.job_id;for(;;){await new Promise(resolve=>setTimeout(resolve,2000));const state=await readResponse(await fetch(apiBase+'/api/workflow/jobs/'+encodeURIComponent(job),{cache:'no-store'}));if(state.status==='complete'){data=state.result;break;}if(state.status==='failed')throw Error(state.detail||t('failed'));}}}
output=data;offlineOutput=offline;render(data,offline);clearInterval(timer);setStatus(offline?'offlineDone':'done',{count:data.plans.length});results.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
}catch(error){clearInterval(timer);setStatus('failed');results.hidden=false;results.replaceChildren(el('p',error instanceof TypeError?t('networkError'):error.message,'error'));}finally{clearInterval(timer);busy=false;for(const b of form.querySelectorAll('button'))b.disabled=false;document.querySelector('#progress').hidden=true;}}
form.addEventListener('submit',event=>{event.preventDefault();submit(false);});document.querySelector('#sample').onclick=()=>submit(true);document.querySelector('#clear').onclick=()=>{document.querySelector('#key').value='';setStatus('cleared');};document.querySelector('#language-button').onclick=()=>setLanguage(language==='zh'?'en':'zh');
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}document.querySelector('#json').onclick=()=>output&&download(JSON.stringify(output,null,2),'application/json','exchangeprep_complete.json');document.querySelector('#md').onclick=()=>output&&download(output.markdown,'text/markdown','exchangeprep_timeline.md');
const year=new Date().getFullYear()+1;form.elements.start_date.value=`${year}-06-01`;form.elements.end_date.value=`${year}-08-31`;form.elements.departure_date.value=`${year}-06-01`;setLanguage(language);
